{"target": {"id": "DemaxPlatform.sol:function:28056:1064", "kind": "function", "contract": "DemaxPlatform", "signature": "swapPrecondition(address)", "visibility": "public", "source": "function swapPrecondition(address token) public view returns (bool) {
        if (token == DGAS || token == WETH) return true;
        uint256 percent = IDemaxConfig(CONFIG).getConfigValue(ConfigNames.TOKEN_TO_DGAS_PAIR_MIN_PERCENT);
        if (!existPair(WETH, DGAS)) return false;
        if (!existPair(DGAS, token)) return false;
        if (!(IDemaxConfig(CONFIG).checkPair(DGAS, token) && IDemaxConfig(CONFIG).checkPair(WETH, token))) return false;
        if (!existPair(WETH, token)) return true;
        if (percent == 0) return true;
        (uint256 reserveDGAS, ) = DemaxSwapLibrary.getReserves(FACTORY, DGAS, token);
        (uint256 reserveWETH, ) = DemaxSwapLibrary.getReserves(FACTORY, WETH, token);
        (uint256 reserveWETH2, uint256 reserveDGAS2) = DemaxSwapLibrary.getReserves(FACTORY, WETH, DGAS);
        uint256 dgasValue = SafeMath.mul(reserveDGAS, reserveWETH2) / reserveDGAS2;
        uint256 limitValue = SafeMath.mul(SafeMath.add(dgasValue, reserveWETH), percent) / PERCENT_DENOMINATOR;
        return dgasValue >= limitValue;
    }"}, "available_context": [{"id": "DemaxPlatform.sol:state_variable:18496:21", "kind": "state_variable", "name": "DemaxPlatform.CONFIG", "reasons": ["state variable declaration: CONFIG"]}, {"id": "DemaxPlatform.sol:function:19500:439", "kind": "function", "name": "initialize(address,address,address,address,address,address,address)", "reasons": ["direct writer of state variable: CONFIG", "direct writer of state variable: DGAS", "direct writer of state variable: FACTORY", "direct writer of state variable: WETH"]}, {"id": "DemaxPlatform.sol:state_variable:18471:19", "kind": "state_variable", "name": "DemaxPlatform.DGAS", "reasons": ["state variable declaration: DGAS"]}, {"id": "DemaxPlatform.sol:state_variable:18523:22", "kind": "state_variable", "name": "DemaxPlatform.FACTORY", "reasons": ["state variable declaration: FACTORY"]}, {"id": "DemaxPlatform.sol:state_variable:18670:51", "kind": "state_variable", "name": "DemaxPlatform.PERCENT_DENOMINATOR", "reasons": ["state variable declaration: PERCENT_DENOMINATOR"]}, {"id": "DemaxPlatform.sol:function:18399:23663", "kind": "function", "name": "slitherConstructorConstantVariables()", "reasons": ["direct writer of state variable: PERCENT_DENOMINATOR"]}, {"id": "DemaxPlatform.sol:state_variable:18551:19", "kind": "state_variable", "name": "DemaxPlatform.WETH", "reasons": ["state variable declaration: WETH"]}], "context_complete": false, "task": "verify_static_analysis_finding", "finding": {"id": "40750c41d2e69ce2f681004ed403a7bd57f9b162a0d6c3b834760a79f4592478", "tool": "slither", "detector": "unused-return", "impact": "Medium", "confidence": "Medium", "description": "DemaxPlatform.swapPrecondition(address) (examples/defihacklabs/evaluation/final20/contracts/burgerswap/raw/DemaxPlatform.sol#728-742) ignores return value by (reserveDGAS,None) = DemaxSwapLibrary.getReserves(FACTORY,DGAS,token) (examples/defihacklabs/evaluation/final20/contracts/burgerswap/raw/DemaxPlatform.sol#736)
